import heapq

def match(orders):
    trades = []
    orders_book = {}  # id -> dict(side, price, qty, arrival, status)
    buy_heap = []   # heap of (-price, arrival, id)
    sell_heap = []  # heap of (price, arrival, id)
    seq = 0

    def clean_top(heap):
        while heap:
            top = heap[0]
            oid = top[2]
            info = orders_book.get(oid)
            if info is None or info['status'] != 'active' or info['qty'] <= 0:
                heapq.heappop(heap)
            else:
                break

    for order in orders:
        seq += 1
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            info = orders_book.get(oid)
            if info is not None and info['status'] == 'active' and info['qty'] > 0:
                info['status'] = 'cancelled'
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            clean_top(opp_heap)
            if not opp_heap:
                break
            top = opp_heap[0]
            if side == 'buy':
                top_price, arrival, resting_id = top
            else:
                neg_price, arrival, resting_id = top
                top_price = -neg_price

            info = orders_book[resting_id]

            if typ != 'market':
                if side == 'buy' and top_price > price:
                    break
                if side == 'sell' and top_price < price:
                    break

            trade_qty = min(remaining, info['qty'])
            if side == 'buy':
                trades.append([oid, resting_id, top_price, trade_qty])
            else:
                trades.append([resting_id, oid, top_price, trade_qty])

            remaining -= trade_qty
            info['qty'] -= trade_qty
            if info['qty'] == 0:
                info['status'] = 'filled'
                heapq.heappop(opp_heap)
            # else stays at top for next iteration

        if typ == 'limit' and remaining > 0:
            orders_book[oid] = {
                'side': side,
                'price': price,
                'qty': remaining,
                'arrival': seq,
                'status': 'active'
            }
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        else:
            # for limit fully filled, or ioc/market, mark status appropriately
            if typ == 'limit':
                if oid not in orders_book:
                    orders_book[oid] = {
                        'side': side,
                        'price': price,
                        'qty': 0,
                        'arrival': seq,
                        'status': 'filled'
                    }
            else:
                # ioc or market - not resting, mark as filled/discarded regardless
                orders_book[oid] = {
                    'side': side,
                    'price': price,
                    'qty': 0,
                    'arrival': seq,
                    'status': 'filled'
                }

    return trades

